txt_c = df['Comments'].fillna('')

def ascii_ratio(s, denom):
    letters = sum(1 for ch in s if ch.isascii() and ch.isalpha())
    if denom == 'nonws':
        d = sum(1 for ch in s if not ch.isspace())
    elif denom == 'all':
        d = len(s)
    elif denom == 'nonws_nopunct':
        d = sum(1 for ch in s if not ch.isspace() and (ch.isalnum()))
    return letters / d if d else 0.0

for denom in ['nonws', 'all', 'nonws_nopunct']:
    for name, series in [('join', txt_join), ('comments', txt_c)]:
        keep = series.map(lambda s: ascii_ratio(s, denom) >= 0.85)
        print(f'denom={denom:15s} series={name:8s} removed={n_raw - keep.sum()}')

import pandas as pd, numpy as np, emoji as emoji_lib, re

df = pd.read_csv('repo/Data/Final_Dataset_Twitter.csv', dtype=str)
n_raw = len(df)
txt_join = (df['Comments'].fillna('') + ',' + df['Unnamed: 1'].fillna('')).tolist()
txt_c = df['Comments'].fillna('').tolist()

def ratio(s, num_mode, den_mode):
    chars = list(s)
    if num_mode == 'ascii_alpha':
        num = sum(1 for ch in chars if ch.isascii() and ch.isalpha())
    elif num_mode == 'ascii':
        num = sum(1 for ch in chars if ch.isascii())
    if den_mode == 'alpha':
        den = sum(1 for ch in chars if ch.isalpha())
    elif den_mode == 'alnum':
        den = sum(1 for ch in chars if ch.isalnum())
    elif den_mode == 'nonws':
        den = sum(1 for ch in chars if not ch.isspace())
    elif den_mode == 'nonemoji':
        den = sum(1 for ch in chars if not emoji_lib.is_emoji(ch))
    return num / den if den else 0.0

for series_name, series in [('join', txt_join), ('comments', txt_c)]:
    for num_mode in ['ascii_alpha', 'ascii']:
        for den_mode in ['alpha', 'alnum', 'nonws', 'nonemoji']:
            keep = np.array([ratio(s, num_mode, den_mode) >= 0.85 for s in series])
            print(f'{series_name:8s} num={num_mode:11s} den={den_mode:9s} removed={n_raw - keep.sum()}')

import pandas as pd, numpy as np, emoji as emoji_lib, re

df = pd.read_csv('repo/Data/Final_Dataset_Twitter.csv', dtype=str)
n_raw = len(df)
txt = (df['Comments'].fillna('') + ',' + df['Unnamed: 1'].fillna('')).tolist()

URL = re.compile(r'https?://\S+|www\.\S+|pic\.twitter\.com/\S+')
MENTION = re.compile(r'@\w+')
EMOJI_RE = emoji_lib.emoji_list

def strip_emoji(s):
    out = s
    parts = []
    last = 0
    for m in EMOJI_RE(s):
        parts.append(s[last:m['match_start']])
        last = m['match_end']
    parts.append(s[last:])
    return ' '.join(parts) if parts else s

def clean(s, lowercase=True, urls=True, mentions=True, hashsym=True, emojis=True):
    if lowercase: s = s.lower()
    if urls: s = URL.sub(' ', s)
    if mentions: s = MENTION.sub(' ', s)
    if hashsym: s = s.replace('#', ' ')
    if emojis: s = strip_emoji(s)
    s = re.sub(r'\s+', ' ', s).strip()
    return s

variants = {
    'raw': txt,
    'clean_full': [clean(s) for s in txt],
    'clean_no_emoji_strip': [clean(s, emojis=False) for s in txt],
    'clean_no_url_strip': [clean(s, urls=False) for s in txt],
    'emoji_stripped_only': [strip_emoji(s) for s in txt],
    'lower_only': [s.lower() for s in txt],
}

def counts(s):
    a = sum(1 for ch in s if ch.isascii() and ch.isalpha())
    al = sum(1 for ch in s if ch.isalpha())
    nw = sum(1 for ch in s if not ch.isspace())
    an = sum(1 for ch in s if ch.isalnum())
    L = len(s)
    return a, al, nw, an, L

for vname, series in variants.items():
    stats = [counts(s) for s in series]
    for den_i, dname in [(1, 'alpha'), (2, 'nonws'), (3, 'alnum'), (4, 'len')]:
        for strict in [False, True]:
            rem = 0
            for a, al, nw, an, L in stats:
                den = [al, nw, an, L][den_i]
                r = a / den if den else 0.0
                ok = (r > 0.85) if strict else (r >= 0.85)
                if not ok: rem += 1
            if 260 <= rem <= 290:
                print(f'{vname:22s} den={dname:6s} strict={strict} removed={rem}')

