import pandas as pd, numpy as np, emoji as emoji_lib, re, collections

df = pd.read_csv('repo/Data/Final_Dataset_Twitter.csv', dtype=str)
n_raw = len(df)
txt = (df['Comments'].fillna('') + ',' + df['Unnamed: 1'].fillna('')).tolist()

def ascii_alpha_ratio(s):
    a = sum(1 for ch in s if ch.isascii() and ch.isalpha())
    al = sum(1 for ch in s if ch.isalpha())
    return (a / al) if al else 0.0

def canon(e):
    return ''.join(ch for ch in e if not (0x1F3FB <= ord(ch) <= 0x1F3FF) and ord(ch) != 0xFE0F)

def emojis_of(s):
    out = []
    for m in emoji_lib.emoji_list(s):
        c = canon(m['emoji'])
        if c:
            out.append(c)
    return out

for name, series in [('raw', txt), ('split_comments', df['Comments'].fillna('').tolist())]:
    keep = np.array([ascii_alpha_ratio(s) >= 0.85 for s in series])
    kept = [s for s, k in zip(series, keep) if k]
    em = [emojis_of(s) for s in kept]
    n_noemoji = sum(1 for e in em if not e)
    final = n_raw - (~keep).sum() - n_noemoji
    cnt = collections.Counter(e[0] for e in em if e)
    panel = {k: v for k, v in cnt.items() if v >= 15}
    print(f'{name:16s} removed={int((~keep).sum())} kept={len(kept)} noemoji={n_noemoji} final={final} '
          f'panel_n={len(panel)} panel_tweets={sum(panel.values())}')
    if len(panel) == 62:
        tot15 = sum(v for v in cnt.values() if v == 15)
        print('   min counts:', sorted(panel.values())[:8])

import pandas as pd, numpy as np, emoji as emoji_lib, collections

df = pd.read_csv('repo/Data/Final_Dataset_Twitter.csv', dtype=str)
txt_join = (df['Comments'].fillna('') + ',' + df['Unnamed: 1'].fillna('')).tolist()

def ascii_alpha_ratio(s):
    a = sum(1 for ch in s if ch.isascii() and ch.isalpha())
    al = sum(1 for ch in s if ch.isalpha())
    return (a / al) if al else 0.0

def canon(e):
    return ''.join(ch for ch in e if not (0x1F3FB <= ord(ch) <= 0x1F3FF) and ord(ch) != 0xFE0F)

def emojis_of(s):
    return [c for m in emoji_lib.emoji_list(s) if (c := canon(m['emoji']))]

for name, series in [('join', txt_join), ('comments', df['Comments'].fillna('').tolist())]:
    kept = [s for s in series if ascii_alpha_ratio(s) >= 0.85]
    em = [emojis_of(s) for s in kept]
    cnt = collections.Counter(e[0] for e in em if e)
    panel = {k: v for k, v in cnt.items() if v >= 15}
    print('=' * 20, name, 'panel size', len(panel), 'coverage', sum(panel.values()))
    for k, v in sorted(panel.items(), key=lambda kv: -kv[1]):
        names = emoji_lib.demojize(k)
        print(f'{k}  {v:5d}  {names}')

import pandas as pd, numpy as np, re, itertools

df = pd.read_csv('repo/Data/Final_Dataset_Twitter.csv', dtype=str)
txt = df['Comments'].fillna('').tolist()

def char_ratio(s, den):
    a = sum(1 for ch in s if ch.isascii() and ch.isalpha())
    if den == 'alpha': d = sum(1 for ch in s if ch.isalpha())
    elif den == 'alnum': d = sum(1 for ch in s if ch.isalnum())
    return a / d if d else 0.0

def tok_ratio(s, strict_tok=True):
    toks = s.split()
    if not toks: return 0.0
    good = sum(1 for t in toks if t.isascii() and t.isalpha())
    return good / len(toks)

res = {}
for den in ['alpha', 'alnum']:
    for thr_op in ['ge', 'gt']:
        rem = sum(1 for s in txt if not ((char_ratio(s, den) >= 0.85) if thr_op == 'ge' else (char_ratio(s, den) > 0.85)))
        res[f'char_{den}_{thr_op}'] = rem

for op in ['ge', 'gt']:
    rem = sum(1 for s in txt if not ((tok_ratio(s) >= 0.85) if op == 'ge' else (tok_ratio(s) > 0.85)))
    res[f'tok_{op}'] = rem

# token-based with punctuation-stripped tokens
def tok_ratio2(s):
    toks = [re.sub(r'^\W+|\W+$', '', t) for t in s.split()]
    toks = [t for t in toks if t]
    if not toks: return 0.0
    return sum(1 for t in toks if t.isascii() and t.isalpha()) / len(toks)

for op in ['ge', 'gt']:
    rem = sum(1 for s in txt if not ((tok_ratio2(s) >= 0.85) if op == 'ge' else (tok_ratio2(s) > 0.85)))
    res[f'tok2_{op}'] = rem

# word-level over alpha-only chunks
for k, v in sorted(res.items(), key=lambda kv: abs(kv[1] - 272)):
    print(f'{k:20s} removed={v}')

